def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    import heapq

    times = sorted({time for start, end, _ in jobs for time in (start, end)})
    index = {time: i for i, time in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, capacity, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path distances are computed in time order.
    infinity = float("inf")
    potential = [infinity] * n
    potential[0] = 0
    for u in range(n):
        for v, capacity, cost, _ in graph[u]:
            if capacity and potential[v] > potential[u] + cost:
                potential[v] = potential[u] + cost

    total_cost = 0
    remaining = k

    while remaining:
        distance = [infinity] * n
        previous = [None] * n
        distance[0] = 0
        heap = [(0, 0)]

        while heap:
            dist_u, u = heapq.heappop(heap)
            if dist_u != distance[u]:
                continue
            for edge_index, (v, capacity, cost, _) in enumerate(graph[u]):
                if capacity:
                    new_dist = dist_u + cost + potential[u] - potential[v]
                    if new_dist < distance[v]:
                        distance[v] = new_dist
                        previous[v] = (u, edge_index)
                        heapq.heappush(heap, (new_dist, v))

        for v in range(n):
            if distance[v] != infinity:
                potential[v] += distance[v]

        flow = remaining
        v = n - 1
        while v:
            u, edge_index = previous[v]
            flow = min(flow, graph[u][edge_index][1])
            v = u

        v = n - 1
        while v:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            edge[1] -= flow
            graph[v][edge[3]][1] += flow
            total_cost += flow * edge[2]
            v = u

        remaining -= flow

    return -total_cost
